#include <cstdint>
#include <string>

namespace
{
    void putUtf16(std::u16string& out, std::uint32_t cp)
    {
        if (cp < 0x10000) { out += static_cast<char16_t>(cp); return; }
        cp -= 0x10000;
        out += static_cast<char16_t>(0xD800 + (cp >> 10));
        out += static_cast<char16_t>(0xDC00 + (cp & 0x3FF));
    }

    void putUtf8(std::string& out, std::uint32_t cp)
    {
        if (cp < 0x80) out += static_cast<char>(cp);
        else if (cp < 0x800) { out += static_cast<char>(0xC0 | (cp >> 6)); out += static_cast<char>(0x80 | (cp & 0x3F)); }
        else if (cp < 0x10000) { out += static_cast<char>(0xE0 | (cp >> 12)); out += static_cast<char>(0x80 | ((cp >> 6) & 0x3F)); out += static_cast<char>(0x80 | (cp & 0x3F)); }
        else { out += static_cast<char>(0xF0 | (cp >> 18)); out += static_cast<char>(0x80 | ((cp >> 12) & 0x3F)); out += static_cast<char>(0x80 | ((cp >> 6) & 0x3F)); out += static_cast<char>(0x80 | (cp & 0x3F)); }
    }
}

std::u16string utf8ToUtf16(const std::string& utf8)
{
    std::u16string out;
    std::size_t i{ 0 };
    while (i < utf8.size())
    {
        const unsigned char b{ static_cast<unsigned char>(utf8[i]) };
        int extra{ -1 };
        std::uint32_t cp{ 0 }, min{ 0 };
        if (b < 0x80) { extra = 0; cp = b; }
        else if ((b & 0xE0) == 0xC0) { extra = 1; cp = b & 0x1F; min = 0x80; }
        else if ((b & 0xF0) == 0xE0) { extra = 2; cp = b & 0x0F; min = 0x800; }
        else if ((b & 0xF8) == 0xF0) { extra = 3; cp = b & 0x07; min = 0x10000; }
        bool ok{ extra >= 0 };
        if (ok && extra > 0)
        {
            if (i + static_cast<std::size_t>(extra) >= utf8.size()) ok = false;   // not enough bytes left
            for (int k{ 1 }; ok && k <= extra; ++k)
            {
                const unsigned char c{ static_cast<unsigned char>(utf8[i + static_cast<std::size_t>(k)]) };
                if ((c & 0xC0) != 0x80) ok = false;
                else cp = (cp << 6) | (c & 0x3F);
            }
            if (ok && (cp < min || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF))) ok = false;
        }
        if (!ok) { out += u'�'; ++i; continue; }
        putUtf16(out, cp);
        i += static_cast<std::size_t>(extra) + 1;
    }
    return out;
}

std::string utf16ToUtf8(const std::u16string& utf16)
{
    std::string out;
    for (std::size_t i{ 0 }; i < utf16.size(); ++i)
    {
        const std::uint32_t u{ utf16[i] };
        if (u >= 0xD800 && u <= 0xDBFF && i + 1 < utf16.size() && utf16[i + 1] >= 0xDC00 && utf16[i + 1] <= 0xDFFF)
        {
            putUtf8(out, 0x10000 + ((u - 0xD800) << 10) + (static_cast<std::uint32_t>(utf16[i + 1]) - 0xDC00));
            ++i;
        }
        else if (u >= 0xD800 && u <= 0xDFFF) putUtf8(out, 0xFFFD);
        else putUtf8(out, u);
    }
    return out;
}

std::size_t codePoints(const std::u16string& utf16)
{
    std::size_t n{ 0 };
    for (std::size_t i{ 0 }; i < utf16.size(); ++i)
    {
        ++n;
        if (utf16[i] >= 0xD800 && utf16[i] <= 0xDBFF && i + 1 < utf16.size() && utf16[i + 1] >= 0xDC00 && utf16[i + 1] <= 0xDFFF) ++i;
    }
    return n;
}

unitTests:
TEST("ASCII and accents") { CHECK(utf8ToUtf16("Hi") == u"Hi"); CHECK(utf8ToUtf16("Gr\xC3\xBC\xC3\x9F" "e") == u"Grüße"); CHECK(utf8ToUtf16("\xE2\x82\xAC") == u"€"); }
TEST("beyond 16 bits") {
    const std::u16string s = utf8ToUtf16("\xF0\x9F\x98\x80");
    CHECK_EQ(s.size(), std::size_t{ 2 }); CHECK_EQ(int(s[0]), 0xD83D); CHECK_EQ(int(s[1]), 0xDE00); CHECK_EQ(codePoints(s), std::size_t{ 1 });
}
TEST("invalid UTF-8") {
    CHECK(utf8ToUtf16("a\x80" "b") == u"a�b");
    CHECK(utf8ToUtf16("\xE2\x82") == u"��");
    CHECK(utf8ToUtf16("\xC0\xAF") == u"��");
    CHECK(utf8ToUtf16("\xED\xA0\x80") == u"���");
    CHECK(utf8ToUtf16("\xF4\x90\x80\x80") == u"����");
    CHECK(utf8ToUtf16("\xFF") == u"�");
}
TEST("UTF-16 to UTF-8") {
    CHECK_EQ(utf16ToUtf8(u"Grüße"), std::string("Gr\xC3\xBC\xC3\x9F" "e"));
    CHECK_EQ(utf16ToUtf8(u"\U0001F600"), std::string("\xF0\x9F\x98\x80"));
    std::u16string lone{ u'a', char16_t(0xD800), u'b' }; CHECK_EQ(utf16ToUtf8(lone), std::string("a\xEF\xBF\xBD" "b"));
    std::u16string low{ char16_t(0xDC00) }; CHECK_EQ(utf16ToUtf8(low), std::string("\xEF\xBF\xBD"));
}
TEST("round trip") { const std::string text = "Xenon \xE2\x9B\xB0 \xF0\x9F\x8C\x8D \xC3\xA9t\xC3\xA9"; CHECK_EQ(utf16ToUtf8(utf8ToUtf16(text)), text); CHECK_EQ(codePoints(utf8ToUtf16(text)), std::size_t{ 13 }); }

